/* selectMasterMpIfOrderQuantityDivsnSaveList */ SELECT '' AS YEAR, A.BUYER, A.STATUS, A.LEGACY_PO_NO, A.LEGACY_PO_SEQ, A.BUYER_ITEM_NO, A.CURRENCY_CODE, A.UNIT_PRICE, A.ITEM_QTY, A.ITEM_AMT, A.ADD_DATE, A.RD_DATE, A.DELY_TO_LOCATION, A.PURCHASER_USER_ID, A.PURCHASER_USER_DEPT, A.AGENT, A.LEGACY_SELLER_CODE, A.LEGACY_PR_NO, A.REQ_USER_ID, A.REQ_USER_NAME, A.REQ_USER_DEPT, A.REQ_USER_DEPT_NAME, A.REMARK, A.REMARK2, A.ERROR_MSG, A.REF_IF_NO, A.DOC_TYPE, A.FILE_NAME, A.SELLER, A.LOAD_DATE, A.LOAD_TIME, A.IF_FLAG, A.BYIT_COMORG_CODE, A.REQ_USER_INFO, NVL(B.AGENT, '') AS PO_AGENT, B.CONTRACT_NO, B.CONTRACT_SEQ, B.UNIT_PRICE FROM IF_PODT A, POIFLOAD_DAEW B WHERE A.BUYER = 'KRDAEW0016' AND A.IF_FLAG = 'S' AND A.BUYER = B.COM_CODE AND A.LEGACY_PO_NO = B.LEGACY_PO_NO AND A.LEGACY_PO_SEQ = B.LEGACY_PO_SEQ AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO
AND B.LEGACY_PO_NO|| '^' ||B.LEGACY_PO_SEQ|| '^' ||B.BUYER_ITEM_NO IN
#{item}
ORDER BY B.LEGACY_PO_NO ,B.LEGACY_PO_SEQ , B.AGENT_SEQ

mapper.update:

UPDATE  IF_PODT SET
	ERROR_MSG			= NVL(#{ERROR_MSG}, ''),
	STATUS				= #{STATUS},
	IF_FLAG				= #{IF_FLAG},
	LOAD_DATE			= TO_CHAR(SYSDATE,'YYYYMMDD'),
	LOAD_TIME			= TO_CHAR(SYSDATE,'HH24MISS')
WHERE  BUYER			= #{BUYER}
AND LEGACY_PO_NO	= #{LEGACY_PO_NO}
AND LEGACY_PO_SEQ	= #{LEGACY_PO_SEQ}
AND BUYER_ITEM_NO	= #{BUYER_ITEM_NO}

mapper.select:
/* getMasterMpIfOrderQuantityDivsnIcomprdtCnt */
	SELECT
		COUNT(*) CNT
	FROM ICOMPRDT
	WHERE BUYER			= #{BUYER}
	AND LEGACY_PO_NO	= #{LEGACY_PO_NO}
	AND LEGACY_PO_SEQ	= #{LEGACY_PO_SEQ}
	AND BUYER_ITEM_NO	= #{BUYER_ITEM_NO}
	AND SAVE_FLAG		= 'PX'
	AND STATUS IN ('C','R')

/* getMasterMpIfOrderQuantityDivsnIcomprdtCnt2 */
	SELECT
		COUNT(*)
	FROM ICOMPRDT
	WHERE BUYER			= #{BUYER}
	AND LEGACY_PO_NO	= #{LEGACY_PO_NO}
	AND LEGACY_PO_SEQ	= #{LEGACY_PO_SEQ}
	AND BUYER_ITEM_NO	= #{BUYER_ITEM_NO}
	AND SAVE_FLAG		= 'PX'
	AND STATUS IN ('C','R')
	AND AGENT				= #{PO_AGENT}
	AND CONTRACT_NO	= #{CONTRACT_NO}
	AND CONTRACT_SEQ	= #{CONTRACT_SEQ}

		/* getMasterMpIfOrderQuantityDivsnPurchaserUserId */
		SELECT
			NVL(USER_ID,' ') AS USER_ID,
            NVL(DEPARTMENT,' ') AS DEPARTMENT
		FROM ICOMLUSR WHERE USER_ID = #{PURCHASER_USER_ID}

SELECT
	NVL(MAX(PRODUCT_CLOSE_FLAG), '') AS PRODUCT_CLOSE_FLAG,
	NVL(MAX(REMARK), '') AS REMARK
FROM V_KEPBYIT
WHERE COM_CODE			= #{BUYER}
AND BUYER_ITEM_NO		= #{BUYER_ITEM_NO}

/* getMasterMpIfOrderQuantityDivsnKepbyit2 */
SELECT
	NVL(UNIT_PRICE,0) UNIT_PRICE,
	NVL(AGENT, '') AGENT,
	NVL(CONTRACT_NO, '') CONTRACT_NO,
	NVL(CONTRACT_SEQ, '') CONTRACT_SEQ
FROM V_KEPBYIT
WHERE COM_CODE				= #{BUYER}
AND BUYER_ITEM_NO			= #{BUYER_ITEM_NO}
AND PRODUCT_CLOSE_FLAG	= 'N'

/* getMasterMpIfOrderQuantityDivsnUnitPrice */
SELECT
	NVL(UNIT_PRICE,0) UNIT_PRICE
FROM V_KEPBYIT
WHERE COM_CODE				= #{BUYER}      
AND BUYER_ITEM_NO			= #{BUYER_ITEM_NO}      
AND AGENT						= #{PO_AGENT}      
AND CONTRACT_NO			= #{CONTRACT_NO}      
AND CONTRACT_SEQ			= #{CONTRACT_SEQ}      
AND PRODUCT_CLOSE_FLAG	= 'N'

/* getMasterMpIfOrderQuantityDivsnUnitPrice2 */
SELECT
	NVL(UNIT_PRICE,0) AS UNIT_PRICE,
	CONTRACT_NO,
	CONTRACT_SEQ
FROM V_KEPBYIT
WHERE COM_CODE				= #{BUYER}
AND BUYER_ITEM_NO			= #{BUYER_ITEM_NO}
AND AGENT						= #{PO_AGENT}
AND PRODUCT_CLOSE_FLAG	= 'N'

/* getMasterMpIfOrderQuantityDivsnIcompodtCnt */
SELECT
	COUNT(*) CNT
FROM ICOMPODT A, ICOMPORS B
WHERE A.BUYER				= B.BUYER
AND A.PO_NO				= B.PO_NO
AND A.PO_SEQ				= B.PO_SEQ
AND A.BUYER				= #{BUYER}
AND A.LEGACY_PO_NO	= #{LEGACY_PO_NO}
AND A.LEGACY_PO_SEQ	= #{LEGACY_PO_SEQ}
AND A.BUYER_ITEM_NO	= #{BUYER_ITEM_NO}


/* getMasterMpIfOrderQuantityDivsnIcomprdtCnt3 */
	SELECT
        COUNT(*) CNT
	FROM ICOMPRDT
	WHERE BUYER			= #{BUYER}
	AND LEGACY_PO_NO	= #{LEGACY_PO_NO}
	AND LEGACY_PO_SEQ	= #{LEGACY_PO_SEQ}
	AND BUYER_ITEM_NO	= #{BUYER_ITEM_NO}
	AND AGENT				=  'KRIFFI0001'
	AND SAVE_FLAG		= 'PX'
	AND RECV_FLAG		= 'GA'
	AND STATUS				<> 'D'

/* selectMasterMpIfOrderQuantityDivsnSaveList2 */ SELECT MAX(A.BUYER) BUYER , MAX(A.STATUS) STATUS , MAX(A.LEGACY_PO_NO) LEGACY_PO_NO , MAX(A.LEGACY_PO_SEQ) LEGACY_PO_SEQ , MAX(A.BUYER_ITEM_NO) BUYER_ITEM_NO , MAX(B.SELLER_ITEM_NO) SELLER_ITEM_NO, MAX(B.DESCRIPTION) DESCRIPTION , MAX(B.SPECIFICATION) SPECIFICATION , MAX(B.UNIT_MEASURE) UNIT_MEASURE , MAX(A.CURRENCY_CODE) CURRENCY_CODE , NVL(MAX(A.UNIT_PRICE), 0) UNIT_PRICE, NVL(MAX(D.ITEM_QTY), 0) ITEM_QTY, NVL(MAX(A.UNIT_PRICE * D.ITEM_QTY) ,0) TOTAL_PRICE, MAX(A.ADD_DATE) ADD_DATE , MAX(A.RD_DATE) RD_DATE , MAX(B.MAKER_CODE) MAKER_CODE , MAX(B.MAKER_NAME) MAKER_NAME , MAX(B.MAKER_PART_NO) MAKER_PART_NO , NVL(MAX(A.DELY_TO_LOCATION), '') DELY_TO_LOCATION , MAX(A.LEGACY_SELLER_CODE) LEGACY_SELLER_CODE, MAX(A.LEGACY_PR_NO) LEGACY_PR_NO , MAX(B.CONTRACT_NO) CONTRACT_NO , MAX(B.CONTRACT_SEQ) CONTRACT_SEQ , MAX(A.REQ_USER_ID) REQ_USER_ID , MAX(A.REQ_USER_NAME) REQ_USER_NAME , MAX(A.REQ_USER_DEPT) REQ_USER_DEPT , MAX(A.REQ_USER_DEPT_NAME) REQ_USER_DEPT_NAME, MAX(A.REQ_USER_INFO) REQ_USER_INFO , NVL(MAX(B.LIST_PRICE),0) LIST_PRICE, MAX(B.AGENT) AGENT , MAX(A.PURCHASER_USER_ID) PURCHASER_USER_ID , MAX(C.USER_NAME_LOC) USER_NAME_LOC , MAX(C.PHONE_NUMBER) PHONE_NUMBER , MAX(C.DEPARTMENT) DEPARTMENT , MAX(A.REMARK) REMARK , MAX(A.REMARK2) REMARK2 , MAX(A.REF_IF_NO) REF_IF_NO , MAX(A.SELLER) SELLER , MAX(A.DOC_TYPE) DOC_TYPE , MAX(A.BYIT_COMORG_CODE) BYIT_COMORG_CODE , MAX(B.PROCESS_TYPE) PROCESS_TYPE , MAX(E.CATEGORY_NO) CATEGORY_NO, NVL(MAX(E.CMS_CATEG_ID), ' ') CMS_CATEG_ID, NVL(MAX(E.CMS_CATLG_ID), ' ') CMS_CATLG_ID, NVL(MAX(E.ITEM_GROUP), ' ') ITEM_GROUP FROM IF_PODT A, ICOMCQDT B, ICOMLUSR C, POIFLOAD_DAEW D, ICOMBYIT E WHERE A.BUYER = 'KRDAEW0016' AND A.BUYER = D.COM_CODE AND A.LEGACY_PO_NO = D.LEGACY_PO_NO AND A.LEGACY_PO_SEQ = D.LEGACY_PO_SEQ AND A.BUYER_ITEM_NO = D.BUYER_ITEM_NO AND A.IF_FLAG = 'S' AND A.BYIT_COMORG_CODE = B.BUYER AND D.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND D.CONTRACT_NO = B.CONTRACT_NO AND D.CONTRACT_SEQ = B.CONTRACT_SEQ AND D.AGENT = B.AGENT AND A.BYIT_COMORG_CODE = E.BUYER AND A.BUYER_ITEM_NO = E.BUYER_ITEM_NO AND A.PURCHASER_USER_ID = C.USER_ID(+)
AND D.LEGACY_PO_NO|| '^' || D.LEGACY_PO_SEQ|| '^' || D.BUYER_ITEM_NO IN
#{item}
GROUP BY D.COM_CODE , D.LEGACY_PO_NO ,D.LEGACY_PO_SEQ , D.AGENT_SEQ ORDER BY D.LEGACY_PO_NO ,D.LEGACY_PO_SEQ , D.AGENT_SEQ

/* selectMasterMpIfOrderQuantityDivsnSaveList3 */ SELECT /*+index(A ICOMPRDT_11)*/ NVL(A.BUYER ,' ') AS BUYER, ' ' AS PO_NO, ' ' AS PO_SEQ, NVL(A.SELLER ,' ') AS SELLER, 'C' AS STATUS, TO_CHAR(SYSDATE,'YYYYMMDD') AS ADD_DATE, TO_CHAR(SYSDATE,'HH24MISS') AS ADD_TIME, TO_CHAR(SYSDATE,'YYYYMMDD') AS CHANGE_DATE, TO_CHAR(SYSDATE,'HH24MISS') AS CHANGE_TIME, NVL(A.BUYER_ITEM_NO ,' ') AS BUYER_ITEM_NO, NVL(A.SELLER_ITEM_NO ,' ') AS SELLER_ITEM_NO, NVL(A.DESCRIPTION ,' ') AS DESCRIPTION, NVL(A.SPECIFICATION ,' ') AS SPECIFICATION, NVL(A.UNIT_MEASURE ,' ') AS UNIT_MEASURE, NVL(A.PO_QTY ,0 ) AS ITEM_QTY, NVL(A.TARGET_PRICE ,0 ) AS UNIT_PRICE, NVL(A.PO_QTY * A.TARGET_PRICE ,0 ) AS ITEM_AMT, NVL(A.RD_DATE ,' ') AS RD_DATE, NVL(A.MAKER_CODE ,' ') AS MAKER_CODE, NVL(A.MAKER_NAME ,' ') AS MAKER_NAME, 'DO' AS DOM_EXP_FLAG, NVL(A.DELY_TO_LOCATION ,' ') AS DELY_TO_LOCATION, 'N' AS COMPLETE_MARK, NVL(A.PR_NO ,' ') AS PR_NO, NVL(A.PR_SEQ ,' ') AS PR_SEQ, NVL(A.REF_PR_NO ,' ') AS REF_PR_NO, NVL(A.CONTRACT_NO ,' ') AS CONTRACT_NO, NVL(A.CONTRACT_SEQ ,' ') AS CONTRACT_SEQ, 'PX' AS PROXY_BUY_FLAG, NVL(A.LIST_PRICE ,0 ) AS AGENT_PRICE, NVL(A.PO_QTY * A.LIST_PRICE ,0 ) AS AGENT_ITEM_AMT, NVL(A.CHANGE_USER_DEPT ,' ') AS CHANGE_USER_DEPT, NVL(A.LEGACY_PO_NO ,' ') AS LEGACY_PO_NO, NVL(A.CHANGE_USER_ID ,' ') AS CHANGE_USER_ID, NVL(A.LEGACY_PO_SEQ ,' ') AS LEGACY_PO_SEQ, NVL(A.REF_IF_NO ,' ') AS REF_IF_NO, 'N' AS DS_FLAG, NVL(A.BYIT_COMORG_CODE ,' ') AS BYIT_COMORG_CODE, NVL(A.PROCESS_TYPE ,' ') AS PROCESS_TYPE, NVL((SELECT ORIGIN_AGENT FROM ICOMCQDT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ), ' ') AS WAREHOUSE_CODE, A.AGENT, A.REQ_USER_INFO, A.DOC_TYPE, A.CATEG_ID, A.REMARK, NVL((SELECT CMS_CATEG_ID FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO AND STATUS <> 'D'), ' ') AS CMS_CATEG_ID, NVL((SELECT CMS_CATLG_ID FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO AND STATUS <> 'D'), ' ') AS CMS_CATLG_ID, NVL((SELECT ITEM_GROUP FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO AND STATUS <> 'D'), ' ') AS ITEM_GROUP, NVL((SELECT KEP_PRICE FROM ICOMCQDT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ), 0) AS KEP_PRICE FROM ICOMPRDT A WHERE BUYER = 'KRDAEW0016' AND A.RECV_FLAG = 'PC' AND A.STATUS <> 'D' AND A.PR_NO|| '^' || TO_NUMBER(A.PR_SEQ) IN
#{item}
ORDER BY BUYER, SELLER, LEGACY_PO_NO, PROCESS_TYPE, DELY_TO_LOCATION, AGENT, REQ_USER_INFO, DOC_TYPE, LEGACY_PO_SEQ, BUYER_ITEM_NO

mapper.update:
UPDATE ICOMSQMT SET
	YEAR = DECODE(YEAR,TO_CHAR(SYSDATE,'YYYY'), YEAR, TO_CHAR(SYSDATE,'YYYY')) ,
	CUR_NO = DECODE(YEAR,TO_CHAR(SYSDATE,'YYYY'),CUR_NO+1,1)
WHERE COMPANY = #{COMPANY}
AND DOC_TYPE = #{DOC_TYPE}


UPDATE  ICOMPRHD SET
CHANGE_DATE =  TO_CHAR(SYSDATE,'YYYYMMDD'),
CHANGE_TIME =  TO_CHAR(SYSDATE,'HH24MISS')
WHERE BUYER = #{BUYER}
AND PR_NO = #{PR_NO}


UPDATE  IF_PODT
SET IF_FLAG = 'Y'
WHERE BUYER			= #{BUYER}
AND LEGACY_PO_NO	= #{LEGACY_PO_NO}
AND LEGACY_PO_SEQ	= #{LEGACY_PO_SEQ}
AND BUYER_ITEM_NO	= #{BUYER_ITEM_NO}


UPDATE ICOMCQDT SET
	PO_QTY				= NVL(PO_QTY,0) + #{ITEM_QTY},
	LAST_PO_PRICE		= #{UNIT_PRICE},
	LAST_PO_QTY		= #{ITEM_QTY},
	LAST_PO_DATE		= TO_CHAR(SYSDATE,'YYYYMMDD')
WHERE BUYER			= #{BUYER}
AND SELLER				= #{SELLER}
AND CONTRACT_NO	= #{CONTRACT_NO}
AND CONTRACT_SEQ	= #{CONTRACT_SEQ}


UPDATE  IF_PODT SET
	CHANGE_USER_ID	=  #{st_user_id},
	CHANGE_DATE		=  TO_CHAR(SYSDATE,'YYYYMMDD'),
	CHANGE_TIME		=  TO_CHAR(SYSDATE,'HH24MISS'),
	IF_FLAG				=  'D'
WHERE BUYER			= #{BUYER}
AND LEGACY_PO_NO	= #{LEGACY_PO_NO}
AND LEGACY_PO_SEQ	= #{LEGACY_PO_SEQ}

mapper.select:

/* selectLastLoginIdWithIfInfo */
SELECT	PURCHASER_USER_ID
,			REQ_USER_ID
FROM	IF_PODT
WHERE	1=1
AND		BUYER = #{BUYER}
AND		LEGACY_PO_NO = #{LEGACY_PO_NO}
AND		LEGACY_PO_SEQ = #{LEGACY_PO_SEQ}
AND		IF_FLAG <> 'D'
